+                        acc, vt, simd<fp16, QR * 16>(P.template select<QR * KT, 1>(t * QR * KT)));
+                }
+                oc = acc;
+            }
+        }
+
+        // ---- normalise + store
+        simd<float, QR> inv = 1.0f / l;
+        simd<float, QR> lse_r = (m + log2(l)) * (1.0f / LOG2E);
